/* Авторские задачи ЕГЭ по графикам и анализу физических данных. */
(() => {
  const format = number => String(Number(number.toFixed(5))).replace('.', ',');
  const graph = (caption, labels, values) => ({dataChart:{kind:'line',caption,labels,values}});
  const table = (caption, columns, rows) => ({dataChart:{kind:'table',caption,columns,rows,labels:[],values:[]}});

  const templates = [
    ['Скорость по графику координаты','м/с',n=>[
      'На графике показано равномерное движение вдоль оси x. Найди проекцию скорости в м/с.',n,
      'Скорость равна угловому коэффициенту графика координаты.',
      `vₓ = Δx/Δt = (${3+4*n} − 3)/4 = ${n} м/с.`,
      graph('Координата x в метрах от времени t',['0 с','2 с','4 с'],[3,3+2*n,3+4*n])]],
    ['Ускорение по графику скорости','м/с²',n=>[
      'На графике показана проекция скорости тела. Найди проекцию ускорения на участке от 2 до 4 с.',n/2,
      'На прямолинейном участке графика aₓ = Δvₓ/Δt.',
      `Скорость изменилась с 3 до ${3+n} м/с за 2 с. Ускорение равно ${n}/2 = ${format(n/2)} м/с².`,
      graph('Проекция скорости vₓ в м/с от времени t',['0 с','2 с','4 с','6 с'],[3,3,3+n,3+n])]],
    ['Путь по графику скорости','м',n=>[
      'Скорость всё время положительна. Участки графика между отмеченными точками прямые. Найди путь тела за первые 6 секунд.',8*n,
      'Путь равен площади под графиком скорости. Разбей её на три трапеции.',
      `За первые 2 с тело проходит ${2*n} м, за следующие 2 с — ${3*n} м, за последние 2 с — ${3*n} м. В сумме ${8*n} м.`,
      graph('Скорость v в м/с от времени t',['0 с','2 с','4 с','6 с'],[n,n,2*n,n])]],
    ['Жёсткость по графику силы','Н/м',n=>[
      'На графике показан модуль силы упругости при растяжении пружины. Найди жёсткость пружины в Н/м.',50*n,
      'По закону Гука жёсткость равна отношению силы к удлинению в метрах.',
      `При удлинении 4 см сила равна ${2*n} Н. Тогда k = ${2*n}/0,04 = ${50*n} Н/м.`,
      graph('Сила упругости в ньютонах от удлинения',['0 см','2 см','4 см'],[0,n,2*n])]],
    ['Работа газа по диаграмме','Дж',n=>[
      'На диаграмме показано изобарное расширение газа. Найди работу, которую газ совершил от первого до последнего состояния.',40*n,
      'При постоянном давлении площадь под линией процесса равна pΔV. 1 кПа·л = 1 Дж.',
      `Объём вырос с 2 до 6 л при давлении ${10*n} кПа. A = ${10*n}·(6 − 2) = ${40*n} Дж.`,
      graph('Давление газа в кПа от объёма',['2 л','4 л','6 л'],[10*n,10*n,10*n])]],
    ['Сопротивление по таблице','Ом',n=>[
      'В таблице приведены измерения напряжения и тока для одного омического резистора. Найди его сопротивление в омах.',2*n,
      'Для резистора R = U/I. Используй напряжение и ток из одной строки.',
      `Во втором опыте U = ${4*n} В, I = 2 А. Поэтому R = ${4*n}/2 = ${2*n} Ом.`,
      table('Измерения в цепи',['Напряжение, В','Ток, А'],[1,2,3].map(i=>[2*n*i,i]))]],
    ['Температура во время нагрева','°C/мин',n=>[
      'По таблице найди среднюю скорость роста температуры с 2-й до 6-й минуты в °C/мин.',n/2,
      'Скорость роста температуры равна отношению изменения температуры к длительности интервала.',
      `Температура выросла на ${2*n} °C за 4 минуты. Средняя скорость равна ${format(n/2)} °C/мин.`,
      table('Нагрев образца',['Время, мин','Температура, °C'],[[0,18],[2,20+n],[4,20+2*n],[6,20+3*n]])]],
    ['Плотность по серии измерений','г/см³',n=>[
      'Три образца сделаны из однородного материала. По таблице найди плотность материала в г/см³.',1+n/10,
      'Выбери любую строку и раздели массу на соответствующий объём.',
      `Для второго образца ρ = ${20+2*n}/20 = ${format(1+n/10)} г/см³.`,
      table('Масса образцов',['Объём, см³','Масса, г'],[1,2,3].map(i=>[10*i,(10+n)*i]))]],
    ['Период полураспада по графику','мин',n=>[
      'На графике показано среднее число нераспавшихся ядер одного изотопа в разные моменты. Линии соединяют отсчёты. Определи период полураспада в минутах.',n,
      'Найди первый отсчёт, где остаётся половина исходного числа ядер.',
      `Половина от 800 — 400. На графике этому числу соответствует t = ${n} мин.`,
      graph('Число ядер от времени',['0 мин',n+' мин',2*n+' мин',3*n+' мин'],[800,400,200,100])]],
    ['Выбор измерения по допуску','',n=>{
      const target = 20 + n;
      const correct = n % 4;
      const rows = [0,1,2,3].map(i=>[i+1,format(target+(i === correct ? 0.1 : 0.6+i/10))]);
      return [
        `Номинальное напряжение равно ${target} В. Допустимое отклонение составляет 0,2 В в любую сторону. Укажи номер единственного измерения, которое укладывается в допуск.`,correct+1,
        'Проверь, для какого измерения модуль разности с номиналом не превышает 0,2 В.',
        `В измерении № ${correct+1} отклонение равно 0,1 В. Все остальные значения превышают номинал больше чем на 0,2 В.`,
        table('Проверка напряжения',['Номер измерения','Напряжение, В'],rows)
      ];
    }]
  ];

  for (const [index,[title,unit,build]] of templates.entries()) {
    for (let variant=1; variant<=15; variant++) {
      const [question, rawAnswer, plan, calculation, figure] = build(variant+1);
      const steps = [plan, calculation];
      tasks.push({
        id: `ege-physics-data-${index+1}-${variant}`,
        grade:11, domain:'physics', subject:'physics', exam:'ege', topic:0,
        topicName:'Графики и анализ данных', examTopic:'physics-ege-data',
        level:index<3?0:index<7?1:2,
        title, question, unit, answer:Number(rawAnswer.toFixed(5)), figure,
        hints:[plan], steps, solution:steps.join(' '), review:{plan},
        source:{
          name:'Решу ЕГЭ', id:'Анализ физических процессов', type:'тематический каталог',
          url:'https://phys-ege.sdamgia.ru/test?theme=421',
          note:'Авторская задача МатКлуба. По ссылке доступна дополнительная практика по анализу физических процессов.'
        }
      });
    }
  }
})();

